mapper.select:
SELECT fm.*, ds.category_id
FROM ocean_gis.gis_file_meta fm
JOIN ocean_gis.gis_data_set ds ON ds.id = fm.data_set_id
WHERE fm.deleted = #{deleted}
AND ds.deleted = 0
AND fm.metadata_status = #{q.metadataStatus}
AND fm.data_set_id = #{q.dataSetId}
AND ds.category_id = #{q.categoryId}
AND fm.original_name LIKE CONCAT('%', #{q.originalName}, '%')
AND fm.extension = #{q.extension}
AND fm.upload_status = #{q.uploadStatus}

    AND fm.metadata_status = 'COMPLETED'
    AND EXISTS (
        SELECT 1 FROM ocean_gis.gis_file_spatial_metadata sm WHERE sm.file_meta_id = fm.id



                    AND ST_CoveredBy(sm.geographic_extent, )

                AND ST_Intersects(sm.geographic_extent, )



            AND sm.tile_matrix_set_id = #{q.tileMatrixSetId}
            AND sm.recommended_max_zoom >= #{q.requiredZoom}

    )

ORDER BY fm.create_time DESC, fm.id DESC

mapper.update:
UPDATE ocean_gis.gis_file_meta
SET deleted = 0,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1

mapper.delete:
DELETE FROM ocean_gis.gis_file_meta
WHERE id = #{id}
  AND deleted = 1

mapper.select:
SELECT COUNT(*)
FROM ocean_gis.gis_file_meta
WHERE data_set_id = #{dataSetId}
